"""Read-only bridge lifecycle built from the observed JSON-RPC contract."""
from __future__ import annotations

import time
from dataclasses import dataclass

from .provider import Client
from .restream import Go2Rtc

@dataclass
class Camera:
    checkpoint_id: str
    name: str
    channel: str
    stream_name: str
    refreshed_at: float = 0

class Bridge:
    def __init__(self, client: Client, restream: Go2Rtc, refresh_seconds: int = 45):
        self.client, self.restream, self.refresh_seconds = client, restream, refresh_seconds
        self.cameras: dict[str, Camera] = {}

    def authenticate(self, phone: str, object_id: str, code: str) -> None:
        self.client.authorize(phone, object_id, code)

    def discover(self) -> list[Camera]:
        cameras: dict[str, Camera] = {}
        for obj in self.client.inventory():
            for checkpoint in self.client.checkpoints(str(obj['id'])):
                channel = checkpoint.get('channel')
                checkpoint_id = str(checkpoint['id'])
                if not channel: continue
                cameras[checkpoint_id] = Camera(checkpoint_id, str(checkpoint.get('name','Camera')), str(channel), self.restream.stable_name(checkpoint_id))
        self.cameras = cameras
        return list(cameras.values())

    def refresh(self, checkpoint_id: str) -> Camera:
        camera = self.cameras[checkpoint_id]
        source = self.client.stream(camera.channel)
        self.restream.replace_source(camera.stream_name, source)
        camera.refreshed_at = time.time()
        return camera

    def refresh_due(self) -> list[Camera]:
        now=time.time(); updated=[]
        for camera in self.cameras.values():
            if now-camera.refreshed_at >= self.refresh_seconds:
                updated.append(self.refresh(camera.checkpoint_id))
        return updated
